-- NSE ORDER_STATUS is a read-only reconciliation report.  Evidence is private,
-- append-only, and its payload columns are encrypted using the existing key.
BEGIN;
CREATE SCHEMA IF NOT EXISTS private;
CREATE TABLE private.nse_order_status_requests (
 id pg_catalog.uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(), integration_operation_id pg_catalog.uuid NOT NULL REFERENCES public.integration_operations(id) ON DELETE RESTRICT,
 call_id pg_catalog.uuid NOT NULL, phase pg_catalog.text NOT NULL CHECK(phase IN ('REQUEST','RESULT')),
 payload_ciphertext pg_catalog.bytea NOT NULL, payload_hash pg_catalog.bytea NOT NULL, content_type pg_catalog.text,
 header_metadata pg_catalog.jsonb NOT NULL, http_status pg_catalog.int4, native_status pg_catalog.text,
 normalized_outcome pg_catalog.text NOT NULL, created_at pg_catalog.timestamptz NOT NULL DEFAULT pg_catalog.now(),
 UNIQUE(call_id,phase)
);
CREATE TABLE private.nse_order_status_observations (
 id pg_catalog.uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(), integration_operation_id pg_catalog.uuid NOT NULL REFERENCES public.integration_operations(id) ON DELETE RESTRICT,
 result_request_id pg_catalog.uuid NOT NULL REFERENCES private.nse_order_status_requests(id) ON DELETE RESTRICT,
 observation_count pg_catalog.int4 NOT NULL CHECK(observation_count>=0), invalid_observation_count pg_catalog.int4 NOT NULL CHECK(invalid_observation_count>=0), native_status pg_catalog.text, created_at pg_catalog.timestamptz NOT NULL DEFAULT pg_catalog.now(), UNIQUE(result_request_id)
);
ALTER TABLE private.nse_order_status_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.nse_order_status_observations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.nse_order_status_requests, private.nse_order_status_observations FROM PUBLIC, anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION private.reject_nse_order_status_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'nse_order_status_evidence_append_only'; END $$;
CREATE TRIGGER nse_order_status_requests_append_only BEFORE UPDATE OR DELETE ON private.nse_order_status_requests FOR EACH ROW EXECUTE FUNCTION private.reject_nse_order_status_mutation();
CREATE TRIGGER nse_order_status_observations_append_only BEFORE UPDATE OR DELETE ON private.nse_order_status_observations FOR EACH ROW EXECUTE FUNCTION private.reject_nse_order_status_mutation();
CREATE UNIQUE INDEX event_outbox_one_nse_order_status_idx ON public.event_outbox(entity_type,entity_id,event_type) WHERE event_type='integration.nse.order_status_requested' AND entity_type='integration_operation' AND status IN ('pending','processing','failed');

-- Narrowly extend the established identity validator; every other operation
-- continues through its existing branch unchanged.
CREATE OR REPLACE FUNCTION public.validate_integration_operation_scope() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.integration_accounts a WHERE a.id=NEW.integration_account_id AND a.workspace_id=NEW.workspace_id AND a.integration_key=NEW.integration_key AND a.integration_environment=NEW.integration_environment) THEN RAISE EXCEPTION 'integration_operation_scope_mismatch'; END IF;
 IF NEW.operation_type='ORDER_STATUS_REPORT' THEN
   IF NEW.category<>'RECONCILIATION' OR NEW.safety_class<>'READ_ONLY' OR NEW.api_key<>'ORDER_STATUS' OR NEW.contract_version<>'NNF_1.9.7' OR NEW.operation_purpose IS NOT NULL OR NEW.reconciliation_target_operation_id IS NOT NULL OR NEW.reconciliation_resolution_operation_id IS NOT NULL THEN RAISE EXCEPTION 'nse_order_status_identity_invalid'; END IF;
 ELSIF NEW.operation_type='UCC_VERIFICATION' THEN
   IF NEW.category<>'RECONCILIATION' OR NEW.safety_class<>'READ_ONLY' OR NEW.api_key<>'CLIENT_MASTER_REPORT' OR NEW.operation_purpose NOT IN ('POST_REGISTRATION_VERIFICATION','AMBIGUOUS_WRITE_RECONCILIATION') OR NEW.reconciliation_target_operation_id IS NULL THEN RAISE EXCEPTION 'integration_reconciliation_target_mismatch'; END IF;
 ELSIF NEW.reconciliation_target_operation_id IS NOT NULL OR NEW.operation_purpose IS NOT NULL THEN RAISE EXCEPTION 'integration_reconciliation_target_unexpected'; END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.prepare_nse_order_status(p_workspace_id pg_catalog.uuid,p_investor_profile_id pg_catalog.uuid,p_report pg_catalog.jsonb) RETURNS public.integration_operations LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a public.integration_accounts; o public.integration_operations; f pg_catalog.date; t pg_catalog.date;
BEGIN
 IF p_report IS NULL OR pg_catalog.jsonb_typeof(p_report)<>'object' OR p_report ? 'order_ids' OR p_report ? 'member_unique_ids' THEN RAISE EXCEPTION 'nse_order_status_identifiers_forbidden'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_object_keys(p_report) k WHERE k NOT IN ('from_date','to_date','order_status','transaction_type')) THEN RAISE EXCEPTION 'nse_order_status_request_invalid'; END IF;
 BEGIN f:=(p_report->>'from_date')::pg_catalog.date; t:=(p_report->>'to_date')::pg_catalog.date; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'nse_order_status_date_invalid'; END;
 IF f IS NULL OR t IS NULL OR t<f OR t-f>6 OR p_report->>'order_status' NOT IN ('ALL','PENDING','ACCEPTED','REJECTED','CANCELLED','EXPIRED') OR p_report->>'transaction_type' NOT IN ('ALL','PURCHASE','REDEMPTION','SWITCH','SIP','STP','SWP') THEN RAISE EXCEPTION 'nse_order_status_request_invalid'; END IF;
 SELECT * INTO a FROM public.integration_accounts WHERE workspace_id=p_workspace_id AND investor_profile_id=p_investor_profile_id AND integration_key='NSE_INVEST' AND integration_environment='UAT' AND state='REGISTERED' AND NULLIF(pg_catalog.btrim(external_account_id),'') IS NOT NULL FOR UPDATE;
 IF a.id IS NULL THEN RAISE EXCEPTION 'registered_nse_uat_account_required'; END IF;
 INSERT INTO public.integration_operations(workspace_id,integration_account_id,integration_key,integration_environment,category,safety_class,operation_type,api_key,contract_version,state) VALUES(p_workspace_id,a.id,'NSE_INVEST','UAT','RECONCILIATION','READ_ONLY','ORDER_STATUS_REPORT','ORDER_STATUS','NNF_1.9.7','PREPARED') RETURNING * INTO o;
 UPDATE public.integration_operations SET state='QUEUED' WHERE id=o.id RETURNING * INTO o;
 INSERT INTO public.event_outbox(event_type,payload,status,entity_id,entity_type) VALUES('integration.nse.order_status_requested',p_report||pg_catalog.jsonb_build_object('integration_operation_id',o.id),'pending',o.id,'integration_operation');
 RETURN o;
END $$;
CREATE OR REPLACE FUNCTION public.get_nse_order_status_source(p_integration_operation_id pg_catalog.uuid) RETURNS pg_catalog.jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r pg_catalog.jsonb; BEGIN SELECT pg_catalog.jsonb_build_object('operation_id',o.id,'client_code',a.external_account_id,'from_date',e.payload->>'from_date','to_date',e.payload->>'to_date','order_status',e.payload->>'order_status','transaction_type',e.payload->>'transaction_type') INTO r FROM public.integration_operations o JOIN public.integration_accounts a ON a.id=o.integration_account_id JOIN public.event_outbox e ON e.entity_id=o.id AND e.event_type='integration.nse.order_status_requested' WHERE o.id=p_integration_operation_id AND o.integration_key='NSE_INVEST' AND o.integration_environment='UAT' AND o.category='RECONCILIATION' AND o.safety_class='READ_ONLY' AND o.operation_type='ORDER_STATUS_REPORT' AND o.api_key='ORDER_STATUS' AND o.contract_version='NNF_1.9.7' AND a.state='REGISTERED'; IF r IS NULL THEN RAISE EXCEPTION 'nse_order_status_source_unavailable'; END IF; RETURN r; END $$;
CREATE OR REPLACE FUNCTION public.claim_nse_order_status_event(p_event_outbox_id pg_catalog.uuid,p_max_attempts pg_catalog.int4 DEFAULT 3,p_lease_seconds pg_catalog.int4 DEFAULT 120) RETURNS TABLE(event_outbox_id pg_catalog.uuid,integration_operation_id pg_catalog.uuid,attempt pg_catalog.int4,claim_state pg_catalog.text,claim_token pg_catalog.uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.event_outbox; BEGIN IF p_max_attempts<>3 OR p_lease_seconds NOT BETWEEN 15 AND 900 THEN RAISE EXCEPTION 'invalid_claim_parameters'; END IF; UPDATE public.event_outbox x SET status='processing',retry_count=x.retry_count+1,claim_token=pg_catalog.gen_random_uuid(),claim_expires_at=pg_catalog.now()+(p_lease_seconds::text||' seconds')::interval,claimed_at=pg_catalog.now() WHERE x.id=p_event_outbox_id AND x.event_type='integration.nse.order_status_requested' AND x.status IN ('pending','failed') AND x.retry_count<p_max_attempts RETURNING x.* INTO e; IF e.id IS NULL THEN RETURN QUERY SELECT NULL::uuid,NULL::uuid,0,'no_event'::text,NULL::uuid; RETURN; END IF; RETURN QUERY SELECT e.id,e.entity_id,e.retry_count,'claimed'::text,e.claim_token; END $$;
CREATE OR REPLACE FUNCTION public.start_nse_order_status(p_event_outbox_id pg_catalog.uuid,p_claim_token pg_catalog.uuid,p_call_id pg_catalog.uuid,p_request_payload pg_catalog.text,p_request_content_type pg_catalog.text,p_request_header_metadata pg_catalog.jsonb,p_started_at pg_catalog.timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.event_outbox; o public.integration_operations; q private.nse_order_status_requests; h bytea; BEGIN SELECT * INTO e FROM public.event_outbox WHERE id=p_event_outbox_id FOR UPDATE; IF e.id IS NULL OR e.status<>'processing' OR e.claim_token IS DISTINCT FROM p_claim_token OR e.claim_expires_at<=pg_catalog.now() THEN RAISE EXCEPTION 'claim_not_owned'; END IF; SELECT * INTO o FROM public.integration_operations WHERE id=e.entity_id FOR UPDATE; h:=extensions.digest(pg_catalog.convert_to(p_request_payload,'UTF8'),'sha256'); SELECT * INTO q FROM private.nse_order_status_requests WHERE call_id=p_call_id AND phase='REQUEST'; IF q.id IS NOT NULL THEN IF q.integration_operation_id<>o.id OR q.payload_hash<>h THEN RAISE EXCEPTION 'integration_request_idempotency_conflict'; END IF; RETURN; END IF; IF o.operation_type<>'ORDER_STATUS_REPORT' OR o.state NOT IN ('QUEUED','SUBMISSION_FAILED') THEN RAISE EXCEPTION 'integration_operation_not_submittable'; END IF; INSERT INTO private.nse_order_status_requests(integration_operation_id,call_id,phase,payload_ciphertext,payload_hash,content_type,header_metadata,normalized_outcome) VALUES(o.id,p_call_id,'REQUEST',extensions.pgp_sym_encrypt(p_request_payload,public.integration_payload_encryption_key('integration_payload_encryption_key_v1'),'cipher-algo=aes256, compress-algo=0'),h,p_request_content_type,p_request_header_metadata,'REQUEST_RECORDED'); UPDATE public.integration_operations SET state='SUBMITTING',attempt_count=e.retry_count,submitted_at=p_started_at WHERE id=o.id; END $$;
CREATE OR REPLACE FUNCTION public.finish_nse_order_status(p_event_outbox_id pg_catalog.uuid,p_claim_token pg_catalog.uuid,p_call_id pg_catalog.uuid,p_response_payload pg_catalog.text,p_response_content_type pg_catalog.text,p_response_header_metadata pg_catalog.jsonb,p_http_status pg_catalog.int4,p_completed_at pg_catalog.timestamptz,p_elapsed_ms pg_catalog.int8,p_native_status_value pg_catalog.text,p_observation_count pg_catalog.int4,p_invalid_observation_count pg_catalog.int4,p_normalized_outcome pg_catalog.text,p_error_category pg_catalog.text,p_timeout_occurred pg_catalog.bool,p_network_failure pg_catalog.bool,p_max_attempts pg_catalog.int4 DEFAULT 3) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.event_outbox; o public.integration_operations; q private.nse_order_status_requests; r private.nse_order_status_requests; h bytea; retry boolean; final_state text; BEGIN IF p_max_attempts<>3 THEN RAISE EXCEPTION 'invalid_max_attempts'; END IF; SELECT * INTO q FROM private.nse_order_status_requests WHERE call_id=p_call_id AND phase='REQUEST'; IF q.id IS NULL THEN RAISE EXCEPTION 'request_interaction_not_found'; END IF; SELECT * INTO e FROM public.event_outbox WHERE id=p_event_outbox_id FOR UPDATE; SELECT * INTO o FROM public.integration_operations WHERE id=q.integration_operation_id FOR UPDATE; IF e.id IS NULL OR e.entity_id<>o.id THEN RAISE EXCEPTION 'claim_not_owned'; END IF; h:=extensions.digest(pg_catalog.convert_to(coalesce(p_response_payload,''),'UTF8'),'sha256'); SELECT * INTO r FROM private.nse_order_status_requests WHERE call_id=p_call_id AND phase='RESULT'; IF r.id IS NOT NULL THEN IF r.integration_operation_id<>o.id OR r.payload_hash<>h OR r.http_status IS DISTINCT FROM p_http_status OR r.normalized_outcome<>p_normalized_outcome THEN RAISE EXCEPTION 'integration_result_idempotency_conflict'; END IF; RETURN; END IF; IF e.claim_token IS DISTINCT FROM p_claim_token OR o.state<>'SUBMITTING' THEN RAISE EXCEPTION 'claim_not_owned'; END IF; IF p_normalized_outcome='SUCCESS' AND (p_http_status NOT BETWEEN 200 AND 299 OR p_native_status_value<>'S') THEN RAISE EXCEPTION 'invalid_success_result'; END IF; INSERT INTO private.nse_order_status_requests(integration_operation_id,call_id,phase,payload_ciphertext,payload_hash,content_type,header_metadata,http_status,native_status,normalized_outcome) VALUES(o.id,p_call_id,'RESULT',extensions.pgp_sym_encrypt(coalesce(p_response_payload,''),public.integration_payload_encryption_key('integration_payload_encryption_key_v1'),'cipher-algo=aes256, compress-algo=0'),h,p_response_content_type,p_response_header_metadata,p_http_status,p_native_status_value,p_normalized_outcome) RETURNING * INTO r; INSERT INTO private.nse_order_status_observations(integration_operation_id,result_request_id,observation_count,invalid_observation_count,native_status) VALUES(o.id,r.id,p_observation_count,p_invalid_observation_count,p_native_status_value); retry:=p_normalized_outcome IN ('TRANSPORT_FAILURE','HTTP_RETRYABLE') AND (p_http_status IS NULL OR p_http_status IN (408,429,500,502,503,504)) AND e.retry_count<p_max_attempts; final_state:=CASE WHEN p_normalized_outcome='SUCCESS' THEN 'SUCCESS' WHEN retry THEN 'SUBMISSION_FAILED' WHEN p_normalized_outcome='BUSINESS_FAILURE' THEN 'BUSINESS_FAILED' WHEN p_normalized_outcome LIKE 'HTTP%' THEN 'HTTP_FAILED' ELSE 'SUBMISSION_FAILED' END; UPDATE public.integration_operations SET state=final_state,retry_allowed=retry,native_business_status=p_native_status_value,business_remark_category=p_error_category,completed_at=p_completed_at WHERE id=o.id; UPDATE public.event_outbox SET status=CASE WHEN retry THEN 'failed' ELSE 'completed' END,claim_token=NULL,claim_expires_at=NULL,claimed_by=NULL WHERE id=e.id; END $$;
CREATE OR REPLACE FUNCTION public.recover_expired_nse_order_status_events(p_max_attempts pg_catalog.int4 DEFAULT 3) RETURNS pg_catalog.int4 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE n int; BEGIN IF p_max_attempts<>3 THEN RAISE EXCEPTION 'invalid_max_attempts'; END IF; WITH x AS (UPDATE public.event_outbox e SET status='failed',claim_token=NULL,claim_expires_at=NULL,claimed_by=NULL,error_message='claim_expired' WHERE e.event_type='integration.nse.order_status_requested' AND e.status='processing' AND e.claim_expires_at<=pg_catalog.now() RETURNING e.entity_id,e.retry_count) UPDATE public.integration_operations o SET state='SUBMISSION_FAILED',retry_allowed=x.retry_count<p_max_attempts,completed_at=pg_catalog.now() FROM x WHERE o.id=x.entity_id; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.prepare_nse_order_status(uuid,uuid,jsonb),public.get_nse_order_status_source(uuid),public.recover_expired_nse_order_status_events(int4),public.claim_nse_order_status_event(uuid,int4,int4),public.start_nse_order_status(uuid,uuid,uuid,text,text,jsonb,timestamptz),public.finish_nse_order_status(uuid,uuid,uuid,text,text,jsonb,int4,timestamptz,int8,text,int4,int4,text,text,bool,bool,int4) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prepare_nse_order_status(uuid,uuid,jsonb) TO service_role; GRANT EXECUTE ON FUNCTION public.get_nse_order_status_source(uuid),public.recover_expired_nse_order_status_events(int4),public.claim_nse_order_status_event(uuid,int4,int4),public.start_nse_order_status(uuid,uuid,uuid,text,text,jsonb,timestamptz),public.finish_nse_order_status(uuid,uuid,uuid,text,text,jsonb,int4,timestamptz,int8,text,int4,int4,text,text,bool,bool,int4) TO service_role;
COMMIT;
